#include <mpi.h>
#include <stdio.h>
#include <unistd.h>

int main(int argc, char **argv) {
    char host[MPI_MAX_PROCESSOR_NAME];
    int rank = -1, size = 0, length = 0, sum = 0;
    puts("IPRE_MPI_STAGE=before_init"); fflush(stdout);
    MPI_Init(&argc, &argv);
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);
    MPI_Get_processor_name(host, &length);
    printf("IPRE_MPI_STAGE=after_init rank=%d\n", rank); fflush(stdout);
    int input = rank + 1;
    MPI_Allreduce(&input, &sum, 1, MPI_INT, MPI_SUM, MPI_COMM_WORLD);
    printf("IPRE_MPI_RESULT={\"rank\":%d,\"size\":%d,\"hostname\":\"%s\",\"sum\":%d}\n",
           rank, size, host, sum); fflush(stdout);
    int failed = size != 4 || sum != 10;
    MPI_Finalize();
    return failed;
}
